reply:
```turtle
@prefix ht:   <http://example.org/onto/hypertension#> .
@prefix owl:  <http://www.w3.org/2002/07/owl#> .
@prefix rdf:  <http://www.w3.org/1999/02/22-rdf-syntax-ns#> .
@prefix rdfs: <http://www.w3.org/2000/01/rdf-schema#> .
@prefix xsd:  <http://www.w3.org/2001/XMLSchema#> .
@prefix skos: <http://www.w3.org/2004/02/skos/core#> .

ht: a owl:Ontology ;
    rdfs:label "Hypertension Ontology"@en ;
    rdfs:comment "An ontology modeling hypertension classification, etiology, measurement, treatment, risk factors and target-organ damage as described in the supplied corpus."@en .

#################################################################
# TOP-LEVEL KIND DISJOINTNESS
#################################################################

owl:AllDisjointClasses [
    owl:members ( ht:BloodPressureReading ht:Hypertension ht:Antihypertensive
                  ht:SecondaryCause ht:TargetOrganDamage ht:RiskFactor )
] .

#################################################################
# MEASUREMENT AXIS
#################################################################

ht:BloodPressureReading a owl:Class ;
    rdfs:label "Blood Pressure Reading"@en ;
    skos:definition "A measured pair of systolic and diastolic blood pressure values, expressed in millimetres of mercury."@en ;
    rdfs:subClassOf [ a owl:Restriction ; owl:onProperty ht:hasSystolicValue ;
          owl:qualifiedCardinality 1 ; owl:onDataRange xsd:integer ] ,
      [ a owl:Restriction ; owl:onProperty ht:hasDiastolicValue ;
          owl:qualifiedCardinality 1 ; owl:onDataRange xsd:integer ] .

ht:hasSystolicValue a owl:DatatypeProperty , owl:FunctionalProperty ;
    rdfs:label "has systolic value"@en ;
    skos:definition "The systolic blood pressure value (mmHg) of a blood pressure reading, measured during cardiac contraction."@en ;
    rdfs:domain ht:BloodPressureReading ; rdfs:range xsd:integer .

ht:hasDiastolicValue a owl:DatatypeProperty , owl:FunctionalProperty ;
    rdfs:label "has diastolic value"@en ;
    skos:definition "The diastolic blood pressure value (mmHg) of a blood pressure reading, measured during cardiac relaxation."@en ;
    rdfs:domain ht:BloodPressureReading ; rdfs:range xsd:integer .

ht:hasBloodPressureCategory a owl:ObjectProperty , owl:FunctionalProperty ;
    rdfs:label "has blood pressure category"@en ;
    skos:definition "Relates a blood pressure reading to the single ACC/AHA-2017 category it is realized into based on its numeric values."@en ;
    rdfs:domain ht:BloodPressureReading ; rdfs:range ht:BloodPressureCategory .

ht:isBloodPressureCategoryOf a owl:ObjectProperty ;
    rdfs:label "is blood pressure category of"@en ;
    skos:definition "Inverse of has blood pressure category."@en ;
    owl:inverseOf ht:hasBloodPressureCategory ;
    rdfs:domain ht:BloodPressureCategory ; rdfs:range ht:BloodPressureReading .

#################################################################
# BLOOD PRESSURE CATEGORIES (ACC/AHA 2017 reading-genus bands)
#################################################################

ht:BloodPressureCategory a owl:Class ;
    rdfs:label "Blood Pressure Category"@en ;
    skos:definition "One of the ACC/AHA-2017 classification bands (Normal, Elevated, Stage 1 Hypertension, Stage 2 Hypertension) assigned to a blood pressure reading on the basis of its systolic and diastolic values."@en ;
    rdfs:subClassOf ht:BloodPressureReading ;
    rdfs:comment "Competing guideline category schemes (ESC/ESH grades, JNC7 prehypertension/stage1/stage2, WHO, NICE, ISH) use different thresholds for the same numeric ranges; only the ACC/AHA-2017 scheme is modeled as classes here, per scope clamp."@en .

ht:NormalBloodPressure a owl:Class ;
    rdfs:label "Normal Blood Pressure"@en ;
    rdfs:subClassOf ht:BloodPressureCategory ;
    skos:definition "A blood pressure reading with systolic pressure less than 120 mmHg and diastolic pressure less than 80 mmHg."@en ;
    owl:equivalentClass [ owl:intersectionOf ( ht:BloodPressureReading
        [ a owl:Restriction ; owl:onProperty ht:hasSystolicValue ; owl:someValuesFrom
            [ a rdfs:Datatype ; owl:onDatatype xsd:integer ;
              owl:withRestrictions ( [ xsd:maxExclusive 120 ] ) ] ]
        [ a owl:Restriction ; owl:onProperty ht:hasDiastolicValue ; owl:someValuesFrom
            [ a rdfs:Datatype ; owl:onDatatype xsd:integer ;
              owl:withRestrictions ( [ xsd:maxExclusive 80 ] ) ] ] ) ] .

ht:ElevatedBloodPressure a owl:Class ;
    rdfs:label "Elevated Blood Pressure"@en ;
    rdfs:subClassOf ht:BloodPressureCategory ;
    skos:definition "A blood pressure reading with systolic pressure 120 to 129 mmHg and diastolic pressure less than 80 mmHg; formerly termed prehypertension under JNC7."@en ;
    rdfs:comment "ESC (2024) groups 120-139/70-89 mmHg together as Elevated; ESH/ISH (2023) calls 130-139/85-89 mmHg High-Normal instead."@en ;
    owl:equivalentClass [ owl:intersectionOf ( ht:BloodPressureReading
        [ a owl:Restriction ; owl:onProperty ht:hasSystolicValue ; owl:someValuesFrom
            [ a rdfs:Datatype ; owl:onDatatype xsd:integer ;
              owl:withRestrictions ( [ xsd:minInclusive 120 ] [ xsd:maxInclusive 129 ] ) ] ]
        [ a owl:Restriction ; owl:onProperty ht:hasDiastolicValue ; owl:someValuesFrom
            [ a rdfs:Datatype ; owl:onDatatype xsd:integer ;
              owl:withRestrictions ( [ xsd:maxExclusive 80 ] ) ] ] ) ] .

ht:Stage1Hypertension a owl:Class ;
    rdfs:label "Stage 1 Hypertension"@en ;
    rdfs:subClassOf ht:BloodPressureCategory ;
    skos:definition "A blood pressure reading with systolic pressure 130 to 139 mmHg or diastolic pressure 80 to 89 mmHg."@en ;
    rdfs:comment "ESC/ESH classify this same numeric range as High-Normal rather than hypertension; JNC7 classifies part of this range as Prehypertension."@en ;
    owl:equivalentClass [ owl:intersectionOf ( ht:BloodPressureReading
        [ owl:unionOf (
            [ a owl:Restriction ; owl:onProperty ht:hasSystolicValue ; owl:someValuesFrom
                [ a rdfs:Datatype ; owl:onDatatype xsd:integer ;
                  owl:withRestrictions ( [ xsd:minInclusive 130 ] [ xsd:maxInclusive 139 ] ) ] ]
            [ a owl:Restriction ; owl:onProperty ht:hasDiastolicValue ; owl:someValuesFrom
                [ a rdfs:Datatype ; owl:onDatatype xsd:integer ;
                  owl:withRestrictions ( [ xsd:minInclusive 80 ] [ xsd:maxInclusive 89 ] ) ] ]
        ) ] ) ] .

ht:Stage2Hypertension a owl:Class ;
    rdfs:label "Stage 2 Hypertension"@en ;
    rdfs:subClassOf ht:BloodPressureCategory ;
    skos:definition "A blood pressure reading with systolic pressure of 140 mmHg or greater or diastolic pressure of 90 mmHg or greater."@en ;
    owl:equivalentClass [ owl:intersectionOf ( ht:BloodPressureReading
        [ owl:unionOf (
            [ a owl:Restriction ; owl:onProperty ht:hasSystolicValue ; owl:someValuesFrom
                [ a rdfs:Datatype ; owl:onDatatype xsd:integer ;
                  owl:withRestrictions ( [ xsd:minInclusive 140 ] ) ] ]
            [ a owl:Restriction ; owl:onProperty ht:hasDiastolicValue ; owl:someValuesFrom
                [ a rdfs:Datatype ; owl:onDatatype xsd:integer ;
                  owl:withRestrictions ( [ xsd:minInclusive 90 ] ) ] ]
        ) ] ) ] .

owl:AllDisjointClasses [
    owl:members ( ht:NormalBloodPressure ht:ElevatedBloodPressure ht:Stage1Hypertension ht:Stage2Hypertension )
] .

#################################################################
# MEASUREMENT METHOD / SETTING
#################################################################

ht:MeasurementMethod a owl:Class ;
    rdfs:label "Measurement Method"@en ;
    skos:definition "A technique used to obtain a blood pressure reading."@en .

ht:AuscultatoryMethod a owl:Class ;
    rdfs:label "Auscultatory Method"@en ;
    rdfs:subClassOf ht:MeasurementMethod ;
    skos:definition "A blood pressure measurement technique using a stethoscope and sphygmomanometer in which Korotkoff sounds mark systolic and diastolic pressure."@en .

ht:OscillometricMethod a owl:Class ;
    rdfs:label "Oscillometric Method"@en ;
    rdfs:subClassOf ht:MeasurementMethod ;
    skos:definition "An automated blood pressure measurement technique that derives systolic, diastolic, and mean arterial pressure from oscillations in cuff pressure."@en .

owl:AllDisjointClasses [ owl:members ( ht:AuscultatoryMethod ht:OscillometricMethod ) ] .

ht:hasMeasurementMethod a owl:ObjectProperty ;
    rdfs:label "has measurement method"@en ;
    skos:definition "Relates a blood pressure reading to the technique used to obtain it."@en ;
    rdfs:domain ht:BloodPressureReading ; rdfs:range ht:MeasurementMethod .

ht:isMeasurementMethodOf a owl:ObjectProperty ;
    rdfs:label "is measurement method of"@en ;
    skos:definition "Inverse of has measurement method."@en ;
    owl:inverseOf ht:hasMeasurementMethod ;
    rdfs:domain ht:MeasurementMethod ; rdfs:range ht:BloodPressureReading .

ht:MeasurementSetting a owl:Class ;
    rdfs:label "Measurement Setting"@en ;
    skos:definition "The clinical context in which a blood pressure reading is obtained (office, ambulatory, or home)."@en .

ht:OfficeBloodPressureMeasurement a owl:Class ;
    rdfs:label "Office Blood Pressure Measurement"@en ;
    rdfs:subClassOf ht:MeasurementSetting ;
    skos:definition "Blood pressure measurement taken in a clinical office or hospital setting, subject to the white coat effect."@en .

ht:AmbulatoryBloodPressureMonitoring a owl:Class ;
    rdfs:label "Ambulatory Blood Pressure Monitoring"@en ;
    skos:altLabel "ABPM"@en ;
    rdfs:subClassOf ht:MeasurementSetting ;
    skos:definition "Measurement of blood pressure at regular intervals over a full day-night cycle outside the clinical setting; the reference standard for distinguishing white coat and masked hypertension."@en .

ht:HomeBloodPressureMonitoring a owl:Class ;
    rdfs:label "Home Blood Pressure Monitoring"@en ;
    skos:altLabel "HBPM"@en ;
    rdfs:subClassOf ht:MeasurementSetting ;
    skos:definition "Patient self-measurement of blood pressure outside the clinical setting using a validated home monitoring device."@en .

owl:AllDisjointClasses [
    owl:members ( ht:OfficeBloodPressureMeasurement ht:AmbulatoryBloodPressureMonitoring ht:HomeBloodPressureMonitoring )
] .

ht:hasMeasurementSetting a owl:ObjectProperty , owl:FunctionalProperty ;
    rdfs:label "has measurement setting"@en ;
    skos:definition "Relates a blood pressure reading to the setting in which it was obtained."@en ;
    rdfs:domain ht:BloodPressureReading ; rdfs:range ht:MeasurementSetting .

ht:isMeasurementSettingOf a owl:ObjectProperty ;
    rdfs:label "is measurement setting of"@en ;
    skos:definition "Inverse of has measurement setting."@en ;
    owl:inverseOf ht:hasMeasurementSetting ;
    rdfs:domain ht:MeasurementSetting ; rdfs:range ht:BloodPressureReading .

#################################################################
# HYPERTENSION (disease root) AND THRESHOLD CONTROVERSY
#################################################################

ht:Hypertension a owl:Class ;
    rdfs:label "Hypertension"@en ;
    skos:altLabel "High Blood Pressure"@en ;
    skos:definition "A chronic medical condition characterized by sustained elevation of arterial blood pressure, diagnosed when systolic and/or diastolic pressure persistently meets or exceeds the diagnostic threshold."@en ;
    rdfs:comment "The corpus documents a genuine diagnostic conflict: the 2017 ACC/AHA guideline sets the diagnostic systolic threshold at 130 mmHg, whereas ESC/ESH, JNC7, WHO and ISH guidelines retain 140 mmHg. Both values are modeled as the competing range of hasDiagnosticSystolicThreshold rather than as separate classes."@en .

ht:hasDiagnosticSystolicThreshold a owl:DatatypeProperty , owl:FunctionalProperty ;
    rdfs:label "has diagnostic systolic threshold"@en ;
    skos:definition "The systolic blood pressure value (mmHg) at or above which a guideline diagnoses hypertension."@en ;
    rdfs:domain ht:Hypertension ; rdfs:range xsd:integer .

ht:PrimaryHypertension a owl:Class ;
    rdfs:label "Primary Hypertension"@en ;
    skos:altLabel "Essential Hypertension"@en , "Idiopathic Hypertension"@en ;
    rdfs:subClassOf ht:Hypertension ;
    skos:definition "Hypertension with no single identifiable cause, resulting from a complex interaction of genetic predisposition and environmental factors such as salt sensitivity; accounts for approximately 85-95% of cases."@en .

ht:SecondaryHypertension a owl:Class ;
    rdfs:label "Secondary Hypertension"@en ;
    skos:altLabel "Inessential Hypertension"@en ;
    rdfs:subClassOf ht:Hypertension ;
    skos:definition "Hypertension that is secondary to a specific identifiable underlying cause, such as a renal, endocrine, vascular, respiratory, or drug-induced condition; accounts for approximately 5-15% of cases overall, with much higher prevalence in children and lower prevalence in older adults."@en ;
    rdfs:subClassOf [ a owl:Restriction ; owl:onProperty ht:hasSecondaryCause ; owl:someValuesFrom ht:SecondaryCause ] .

owl:AllDisjointClasses [ owl:members ( ht:PrimaryHypertension ht:SecondaryHypertension ) ] .

ht:hasSecondaryCause a owl:ObjectProperty ;
    rdfs:label "has secondary cause"@en ;
    skos:definition "Relates an instance of secondary hypertension to the identifiable underlying cause responsible for the elevated blood pressure."@en ;
    rdfs:domain ht:SecondaryHypertension ; rdfs:range ht:SecondaryCause .

ht:isSecondaryCauseOf a owl:ObjectProperty ;
    rdfs:label "is secondary cause of"@en ;
    skos:definition "Inverse of has secondary cause."@en ;
    owl:inverseOf ht:hasSecondaryCause ;
    rdfs:domain ht:SecondaryCause ; rdfs:range ht:SecondaryHypertension .

ht:IsolatedSystolicHypertension a owl:Class ;
    rdfs:label "Isolated Systolic Hypertension"@en ;
    rdfs:subClassOf ht:Hypertension ;
    skos:definition "A pattern of hypertension defined by a disproportionate rise in systolic pressure with preserved or low diastolic pressure, producing a widened pulse pressure; the predominant form of hypertension in older adults, due chiefly to age-related arterial stiffening."@en ;
    rdfs:comment "Traditionally defined as systolic pressure above 140 mmHg with diastolic below 90 mmHg; under the 2017 ACC/AHA guideline a systolic pressure of 130 mmHg is considered hypertensive at all ages, lowering this threshold also."@en .

ht:WhiteCoatHypertension a owl:Class ;
    rdfs:label "White Coat Hypertension"@en ;
    skos:altLabel "White Coat Syndrome"@en , "WHT"@en ;
    rdfs:subClassOf ht:Hypertension ;
    skos:definition "A form of labile hypertension in which blood pressure is elevated in the office measurement setting but normal in out-of-office measurement settings, generally attributed to the anxiety of a clinic visit."@en .

ht:MaskedHypertension a owl:Class ;
    rdfs:label "Masked Hypertension"@en ;
    skos:altLabel "MH"@en ;
    rdfs:subClassOf ht:Hypertension ;
    skos:definition "A blood pressure phenotype in which office measurement is normal but out-of-office measurement is elevated, carrying cardiovascular risk approaching that of sustained hypertension."@en .

ht:ResistantHypertension a owl:Class ;
    rdfs:label "Resistant Hypertension"@en ;
    rdfs:subClassOf ht:Hypertension ;
    skos:definition "High blood pressure that remains uncontrolled to goal despite adherence to three suitably dosed antihypertensive medications of different classes, one of which is a diuretic, after confirming adherence and excluding the white coat effect; blood pressure requiring four or more agents is likewise considered resistant."@en ;
    rdfs:subClassOf [ a owl:Restriction ; owl:onProperty ht:hasAntihypertensive ; owl:minQualifiedCardinality "3"^^xsd:nonNegativeInteger ; owl:onClass ht:Antihypertensive ] .

ht:HypertensiveCrisis a owl:Class ;
    rdfs:label "Hypertensive Crisis"@en ;
    rdfs:subClassOf ht:Hypertension ;
    skos:definition "A severe, acute elevation of blood pressure, conventionally a systolic pressure of 180 mmHg or more or a diastolic pressure of 120 mmHg or more, classified into hypertensive urgency or hypertensive emergency according to the presence or absence of acute target-organ damage."@en .

ht:HypertensiveUrgency a owl:Class ;
    rdfs:label "Hypertensive Urgency"@en ;
    rdfs:subClassOf ht:HypertensiveCrisis ;
    skos:definition "A hypertensive crisis without evidence of acute target-organ damage, typically managed with gradual oral reduction of blood pressure over 24 to 48 hours."@en ;
    rdfs:subClassOf [ a owl:Restriction ; owl:onProperty ht:hasTargetOrganDamage ;
        owl:maxQualifiedCardinality "0"^^xsd:nonNegativeInteger ; owl:onClass ht:TargetOrganDamage ] .

ht:HypertensiveEmergency a owl:Class ;
    rdfs:label "Hypertensive Emergency"@en ;
    rdfs:subClassOf ht:HypertensiveCrisis ;
    skos:definition "A hypertensive crisis accompanied by acute hypertension-mediated target-organ damage, requiring immediate but controlled reduction of blood pressure, typically with intravenous agents in a monitored setting."@en ;
    owl:equivalentClass [ owl:intersectionOf ( ht:HypertensiveCrisis
        [ a owl:Restriction ; owl:onProperty ht:hasTargetOrganDamage ; owl:someValuesFrom ht:TargetOrganDamage ] ) ] .

owl:AllDisjointClasses [ owl:members ( ht:HypertensiveUrgency ht:HypertensiveEmergency ) ] .

#################################################################
# SECONDARY CAUSES
#################################################################

ht:SecondaryCause a owl:Class ;
    rdfs:label "Secondary Cause"@en ;
    skos:definition "An identifiable underlying medical condition, vascular anomaly, or substance responsible for secondary hypertension."@en .

ht:RenalCause a owl:Class ;
    rdfs:label "Renal Cause"@en ;
    rdfs:subClassOf ht:SecondaryCause ;
    skos:definition "A secondary cause of hypertension arising from kidney disease, the most common category of secondary hypertension."@en .

ht:RenalParenchymalDisease a owl:Class ;
    rdfs:label "Renal Parenchymal Disease"@en ;
    rdfs:subClassOf ht:RenalCause ;
    skos:definition "Intrinsic kidney tissue disease causing secondary hypertension, including diabetic nephropathy, glomerulonephritis, interstitial disorders, polycystic kidney disease, and lupus nephritis."@en .

ht:RenovascularDisease a owl:Class ;
    rdfs:label "Renovascular Disease"@en ;
    rdfs:subClassOf ht:RenalCause ;
    skos:definition "Hypertension-producing disease of the renal arteries, caused by narrowing that reduces renal blood flow."@en .

ht:RenalArteryStenosis a owl:Class ;
    rdfs:label "Renal Artery Stenosis"@en ;
    rdfs:subClassOf ht:RenovascularDisease ;
    skos:definition "Narrowing of a renal artery, the specific lesion underlying renovascular hypertension, including atherosclerotic renal artery stenosis."@en .

ht:EndocrineCause a owl:Class ;
    rdfs:label "Endocrine Cause"@en ;
    rdfs:subClassOf ht:SecondaryCause ;
    skos:definition "A secondary cause of hypertension arising from a hormonal disturbance."@en .

ht:PrimaryAldosteronism a owl:Class ;
    rdfs:label "Primary Aldosteronism"@en ;
    skos:altLabel "Conn's Syndrome"@en , "Hyperaldosteronism"@en ;
    rdfs:subClassOf ht:EndocrineCause ;
    skos:definition "Autonomous overproduction of aldosterone by the adrenal glands, due to an aldosterone-producing adenoma or bilateral adrenal hyperplasia, which raises blood pressure and may cause hypokalaemia; the most common endocrine cause of secondary hypertension and present in up to one in five patients with resistant hypertension."@en .

ht:Pheochromocytoma a owl:Class ;
    rdfs:label "Pheochromocytoma"@en ;
    rdfs:subClassOf ht:EndocrineCause ;
    skos:definition "A tumor causing excessive secretion of norepinephrine and epinephrine, promoting vasoconstriction and raising blood pressure."@en .

ht:CushingSyndrome a owl:Class ;
    rdfs:label "Cushing Syndrome"@en ;
    rdfs:subClassOf ht:EndocrineCause ;
    skos:definition "A disorder of excess glucocorticoids that can cause secondary hypertension."@en .

ht:Hyperthyroidism a owl:Class ;
    rdfs:label "Hyperthyroidism"@en ;
    rdfs:subClassOf ht:EndocrineCause ;
    skos:definition "Excess thyroid hormone production, a recognized cause of secondary hypertension and of isolated systolic hypertension."@en .

ht:Hypothyroidism a owl:Class ;
    rdfs:label "Hypothyroidism"@en ;
    rdfs:subClassOf ht:EndocrineCause ;
    skos:definition "Deficient thyroid hormone production, a recognized cause of secondary hypertension and of isolated systolic hypertension."@en .

ht:PrimaryHyperparathyroidism a owl:Class ;
    rdfs:label "Primary Hyperparathyroidism"@en ;
    rdfs:subClassOf ht:EndocrineCause ;
    skos:definition "Excess parathyroid hormone secretion recognized as a contributor to secondary hypertension."@en .

ht:VascularCause a owl:Class ;
    rdfs:label "Vascular Cause"@en ;
    rdfs:subClassOf ht:SecondaryCause ;
    skos:definition "A secondary cause of hypertension arising from a structural vascular abnormality."@en .

ht:AorticCoarctation a owl:Class ;
    rdfs:label "Aortic Coarctation"@en ;
    skos:altLabel "Coarctation of the Aorta"@en ;
    rdfs:subClassOf ht:VascularCause ;
    skos:definition "A congenital narrowing of the aorta that typically produces hypertension in younger patients."@en .

ht:ObstructiveSleepApnea a owl:Class ;
    rdfs:label "Obstructive Sleep Apnea"@en ;
    skos:altLabel "OSA"@en ;
    rdfs:subClassOf ht:SecondaryCause ;
    skos:definition "A sleep-related breathing disorder that is one of the most common causes of secondary hypertension."@en .

ht:DrugInducedCause a owl:Class ;
    rdfs:label "Drug Induced Cause"@en ;
    rdfs:subClassOf ht:SecondaryCause ;
    skos:definition "Secondary hypertension caused by a prescription medication, over-the-counter agent, or recreational substance, including NSAIDs, sympathomimetic decongestants, stimulants, corticosteroids, oral contraceptives, cyclosporine, licorice, cocaine, and methamphetamine; identifying and discontinuing the agent may resolve the hypertension."@en .

owl:AllDisjointClasses [
    owl:members ( ht:RenalCause ht:EndocrineCause ht:VascularCause ht:ObstructiveSleepApnea ht:DrugInducedCause )
] .

#################################################################
# RISK FACTORS
#################################################################

ht:RiskFactor a owl:Class ;
    rdfs:label "Risk Factor"@en ;
    skos:definition "A factor, modifiable or non-modifiable, associated with increased likelihood of developing hypertension."@en .

ht:hasRiskFactor a owl:ObjectProperty ;
    rdfs:label "has risk factor"@en ;
    skos:definition "Relates hypertension to a factor associated with increased risk of the condition."@en ;
    rdfs:domain ht:Hypertension ; rdfs:range ht:RiskFactor .

ht:isRiskFactorOf a owl:ObjectProperty ;
    rdfs:label "is risk factor of"@en ;
    skos:definition "Inverse of has risk factor."@en ;
    owl:inverseOf ht:hasRiskFactor ;
    rdfs:domain ht:RiskFactor ; rdfs:range ht:Hypertension .

ht:ModifiableRiskFactor a owl:Class ;
    rdfs:label "Modifiable Risk Factor"@en ;
    rdfs:subClassOf ht:RiskFactor ;
    skos:definition "A risk factor for hypertension that can be changed through behavior or treatment, such as diet, weight, activity, tobacco, or alcohol use."@en .

ht:NonModifiableRiskFactor a owl:Class ;
    rdfs:label "Non Modifiable Risk Factor"@en ;
    rdfs:subClassOf ht:RiskFactor ;
    skos:definition "A risk factor for hypertension that cannot be changed, such as age, sex, race, or family history."@en .

owl:AllDisjointClasses [ owl:members ( ht:ModifiableRiskFactor ht:NonModifiableRiskFactor ) ] .

ht:DietarySaltIntake a owl:Class ;
    rdfs:label "Dietary Salt Intake"@en ;
    rdfs:subClassOf ht:ModifiableRiskFactor ;
    skos:definition "Excess salt consumption, a central modifiable risk factor; approximately 50-60% of hypertensive patients are salt-sensitive."@en .

ht:Obesity a owl:Class ;
    rdfs:label "Obesity"@en ;
    rdfs:subClassOf ht:ModifiableRiskFactor ;
    skos:definition "Excess body weight, a modifiable risk factor for hypertension; weight reduction alone can lower systolic pressure by 5 to 20 mmHg."@en .

ht:PhysicalInactivity a owl:Class ;
    rdfs:label "Physical Inactivity"@en ;
    rdfs:subClassOf ht:ModifiableRiskFactor ;
    skos:definition "Lack of regular exercise, a modifiable risk factor for hypertension."@en .

ht:TobaccoUse a owl:Class ;
    rdfs:label "Tobacco Use"@en ;
    rdfs:subClassOf ht:ModifiableRiskFactor ;
    skos:definition "Smoking or other tobacco consumption, a modifiable risk factor for hypertension."@en .

ht:AlcoholConsumption a owl:Class ;
    rdfs:label "Alcohol Consumption"@en ;
    rdfs:subClassOf ht:ModifiableRiskFactor ;
    skos:definition "Excess alcohol intake, a modifiable risk factor associated with higher blood pressure."@en .

ht:AdvancedAge a owl:Class ;
    rdfs:label "Advanced Age"@en ;
    rdfs:subClassOf ht:NonModifiableRiskFactor ;
    skos:definition "Increasing age, a non-modifiable risk factor; prevalence of hypertension rises to approximately 60% of individuals above age 60."@en .

ht:FamilyHistory a owl:Class ;
    rdfs:label "Family History"@en ;
    rdfs:subClassOf ht:NonModifiableRiskFactor ;
    skos:definition "A family history of hypertension, a non-modifiable risk factor reflecting genetic predisposition."@en .

ht:Race a owl:Class ;
    rdfs:label "Race"@en ;
    rdfs:subClassOf ht:NonModifiableRiskFactor ;
    skos:definition "Race or ethnicity, a non-modifiable factor that also influences first-line treatment selection."@en .

ht:Sex a owl:Class ;
    rdfs:label "Sex"@en ;
    rdfs:subClassOf ht:NonModifiableRiskFactor ;
    skos:definition "Biological sex, a non-modifiable risk factor for hypertension."@en .

#################################################################
# TARGET ORGAN DAMAGE
#################################################################

ht:TargetOrganDamage a owl:Class ;
    rdfs:label "Target Organ Damage"@en ;
    skos:altLabel "Hypertension Mediated Organ Damage"@en ;
    skos:definition "Structural or functional injury to the heart, retina, kidney, or brain caused by chronic or acute severe elevation of blood pressure."@en .

ht:hasTargetOrganDamage a owl:ObjectProperty ;
    rdfs:label "has target organ damage"@en ;
    skos:definition "Relates hypertension to the organ damage it has produced."@en ;
    rdfs:domain ht:Hypertension ; rdfs:range ht:TargetOrganDamage .

ht:isTargetOrganDamageOf a owl:ObjectProperty ;
    rdfs:label "is target organ damage of"@en ;
    skos:definition "Inverse of has target organ damage."@en ;
    owl:inverseOf ht:hasTargetOrganDamage ;
    rdfs:domain ht:TargetOrganDamage ; rdfs:range ht:Hypertension .

ht:HypertensiveHeartDisease a owl:Class ;
    rdfs:label "Hypertensive Heart Disease"@en ;
    rdfs:subClassOf ht:TargetOrganDamage ;
    skos:definition "Structural and functional changes in the left ventricle, left atrium, and coronary arteries resulting from chronic blood pressure elevation, which may progress to heart failure."@en .

ht:LeftVentricularHypertrophy a owl:Class ;
    rdfs:label "Left Ventricular Hypertrophy"@en ;
    rdfs:subClassOf ht:HypertensiveHeartDisease ;
    skos:definition "Thickening of the left ventricular wall in compensatory response to chronic pressure overload; the hallmark structural manifestation of hypertensive heart disease and a strong predictor of cardiovascular events."@en .

ht:HypertensiveRetinopathy a owl:Class ;
    rdfs:label "Hypertensive Retinopathy"@en ;
    rdfs:subClassOf ht:TargetOrganDamage ;
    skos:definition "Damage to the retina and retinal circulation caused by sustained or abrupt elevation of blood pressure, visible on dilated fundoscopic examination and correlated with the severity and chronicity of hypertension."@en ;
    rdfs:subClassOf [ a owl:Restriction ; owl:onProperty ht:hasRetinalFinding ; owl:someValuesFrom ht:RetinalFinding ] .

ht:RetinalFinding a owl:Class ;
    rdfs:label "Retinal Finding"@en ;
    skos:definition "A named clinical sign of retinal vascular damage observed on ophthalmoscopy in hypertensive retinopathy."@en .

ht:hasRetinalFinding a owl:ObjectProperty ;
    rdfs:label "has retinal finding"@en ;
    skos:definition "Relates hypertensive retinopathy to a specific retinal finding it presents."@en ;
    rdfs:domain ht:HypertensiveRetinopathy ; rdfs:range ht:RetinalFinding .

ht:isRetinalFindingOf a owl:ObjectProperty ;
    rdfs:label "is retinal finding of"@en ;
    skos:definition "Inverse of has retinal finding."@en ;
    owl:inverseOf ht:hasRetinalFinding ;
    rdfs:domain ht:RetinalFinding ; rdfs:range ht:HypertensiveRetinopathy .

ht:ArteriolarNarrowing a owl:Class ;
    rdfs:label "Arteriolar Narrowing"@en ;
    rdfs:subClassOf ht:RetinalFinding ;
    skos:definition "Generalized or focal narrowing of the retinal arterioles, the earliest sign of hypertensive retinopathy."@en .

ht:ArteriovenousNicking a owl:Class ;
    rdfs:label "Arteriovenous Nicking"@en ;
    skos:altLabel "AV Nipping"@en ;
    rdfs:subClassOf ht:RetinalFinding ;
    skos:definition "Compression of a retinal vein at a point where it is crossed by a sclerotic arteriole."@en .

ht:RetinalHemorrhage a owl:Class ;
    rdfs:label "Retinal Hemorrhage"@en ;
    skos:altLabel "Flame Hemorrhage"@en , "Blot Hemorrhage"@en ;
    rdfs:subClassOf ht:RetinalFinding ;
    skos:definition "Bleeding into the retinal tissue, including flame-shaped and blot hemorrhages, resulting from breakdown of the blood-retinal barrier."@en .

ht:CottonWoolSpot a owl:Class ;
    rdfs:label "Cotton Wool Spot"@en ;
    rdfs:subClassOf ht:RetinalFinding ;
    skos:definition "An ischemic lesion of the retinal nerve fiber layer appearing as a pale, fluffy patch, seen in advanced hypertensive retinopathy."@en .

ht:HardExudate a owl:Class ;
    rdfs:label "Hard Exudate"@en ;
    rdfs:subClassOf ht:RetinalFinding ;
    skos:definition "Lipid deposits leaked into the retina through a damaged blood-retinal barrier."@en .

ht:Papilledema a owl:Class ;
    rdfs:label "Papilledema"@en ;
    skos:altLabel "Optic Disc Edema"@en ;
    rdfs:subClassOf ht:RetinalFinding ;
    skos:definition "Swelling of the optic disc, the most severe retinal finding, indicating malignant hypertensive retinopathy."@en .

ht:HypertensiveKidneyDisease a owl:Class ;
    rdfs:label "Hypertensive Kidney Disease"@en ;
    skos:altLabel "Hypertensive Nephropathy"@en , "Hypertensive Nephrosclerosis"@en ;
    rdfs:subClassOf ht:TargetOrganDamage ;
    skos:definition "Damage to kidney tissue, including small blood vessels, glomeruli, tubules, and interstitium, due to chronic high blood pressure, producing hardening and thickening (nephrosclerosis) and progressive loss of renal function that may culminate in kidney failure."@en .

ht:CerebrovascularDisease a owl:Class ;
    rdfs:label "Cerebrovascular Disease"@en ;
    rdfs:subClassOf ht:TargetOrganDamage ;
    skos:definition "Damage to the cerebral vessels and brain resulting from hypertension, predisposing to ischaemic and haemorrhagic stroke and hypertensive encephalopathy."@en .

ht:Stroke a owl:Class ;
    rdfs:label "Stroke"@en ;
    rdfs:subClassOf ht:CerebrovascularDisease ;
    skos:definition "Ischemic or hemorrhagic cerebrovascular injury resulting from hypertensive damage to brain-supplying arteries."@en .

ht:HypertensiveEncephalopathy a owl:Class ;
    rdfs:label "Hypertensive Encephalopathy"@en ;
    rdfs:subClassOf ht:CerebrovascularDisease ;
    skos:definition "Brain swelling and dysfunction caused by severely elevated blood pressure, presenting with headache, confusion, or visual disturbance."@en .

owl:AllDisjointClasses [
    owl:members ( ht:HypertensiveHeartDisease ht:HypertensiveRetinopathy ht:HypertensiveKidneyDisease ht:CerebrovascularDisease )
] .

#################################################################
# ANTIHYPERTENSIVE DRUG CLASSES
#################################################################

ht:Antihypertensive a owl:Class ;
    rdfs:label "Antihypertensive"@en ;
    skos:definition "A medication class used to lower blood pressure in the treatment of hypertension."@en .

ht:hasAntihypertensive a owl:ObjectProperty ;
    rdfs:label "has antihypertensive"@en ;
    skos:definition "Relates hypertension to a class of medication used in its treatment."@en ;
    rdfs:domain ht:Hypertension ; rdfs:range ht:Antihypertensive .

ht:isAntihypertensiveOf a owl:ObjectProperty ;
    rdfs:label "is antihypertensive of"@en ;
    skos:definition "Inverse of has antihypertensive."@en ;
    owl:inverseOf ht:hasAntihypertensive ;
    rdfs:domain ht:Antihypertensive ; rdfs:range ht:Hypertension .

ht:ThiazideDiuretic a owl:Class ;
    rdfs:label "Thiazide Diuretic"@en ;
    rdfs:subClassOf ht:Antihypertensive ;
    skos:definition "A first-line antihypertensive drug class that blocks sodium reabsorption in the distal convoluted tubule, promoting natriuresis and diuresis and causing modest vasodilation; includes thiazide-like agents such as chlorthalidone and indapamide."@en .

ht:AngiotensinConvertingEnzymeInhibitor a owl:Class ;
    rdfs:label "Angiotensin Converting Enzyme Inhibitor"@en ;
    skos:altLabel "ACE Inhibitor"@en , "ACEI"@en ;
    rdfs:subClassOf ht:Antihypertensive ;
    skos:definition "A first-line antihypertensive drug class that inhibits the angiotensin-converting enzyme, reducing angiotensin II production and increasing bradykinin levels, causing vasodilation; particularly beneficial in chronic kidney disease, heart failure, and diabetes."@en .

ht:AngiotensinReceptorBlocker a owl:Class ;
    rdfs:label "Angiotensin Receptor Blocker"@en ;
    skos:altLabel "ARB"@en ;
    rdfs:subClassOf ht:Antihypertensive ;
    skos:definition "A first-line antihypertensive drug class that blocks the binding of angiotensin II to the AT1 receptor, with efficacy similar to ACE inhibitors but less cough and angioedema; generally not combined with ACE inhibitors."@en .

ht:CalciumChannelBlocker a owl:Class ;
    rdfs:label "Calcium Channel Blocker"@en ;
    skos:altLabel "CCB"@en ;
    rdfs:subClassOf ht:Antihypertensive ;
    skos:definition "A first-line antihypertensive drug class that inhibits calcium entry through L-type voltage-gated channels in cardiac and vascular smooth muscle, reducing peripheral resistance or cardiac contractility depending on subtype."@en .

ht:Dihydropyridine a owl:Class ;
    rdfs:label "Dihydropyridine"@en ;
    rdfs:subClassOf ht:CalciumChannelBlocker ;
    skos:definition "A subtype of calcium channel blocker acting predominantly on vascular smooth muscle to cause peripheral vasodilation; the preferred subtype for treating hypertension."@en .

ht:NonDihydropyridine a owl:Class ;
    rdfs:label "Non Dihydropyridine"@en ;
    rdfs:subClassOf ht:CalciumChannelBlocker ;
    skos:definition "A subtype of calcium channel blocker, including verapamil and diltiazem, acting predominantly on cardiac contractility and atrioventricular conduction, better suited to arrhythmia management."@en .

ht:BetaBlocker a owl:Class ;
    rdfs:label "Beta Blocker"@en ;
    rdfs:subClassOf ht:Antihypertensive ;
    skos:definition "An antihypertensive drug class that inhibits catecholamine binding to beta-adrenergic receptors, decreasing heart rate, contractility, and renin release; no longer recommended as first-line therapy except when a compelling cardiac indication is present."@en .

owl:AllDisjointClasses [
    owl:members ( ht:ThiazideDiuretic ht:CalciumChannelBlocker ht:AngiotensinConvertingEnzymeInhibitor
                  ht:AngiotensinReceptorBlocker ht:BetaBlocker )
] .

owl:AllDisjointClasses [ owl:members ( ht:Dihydropyridine ht:NonDihydropyridine ) ] .
